int l2tp_ip6_recvmsg(struct kiocb *iocb, struct sock *sk,
                     struct msghdr *msg, size_t len, int noblock,
                     int flags, int *addr_len)
{
    struct l2tp_session *session = l2tp_sk_to_session(sk);
    struct l2tp_tunnel *tunnel = session->tunnel;
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;
    struct ipv6hdr *iph;
    struct in6_addr *saddr, *daddr;

    if (flags & MSG_OOB)
        return -EOPNOTSUPP;

    if (flags & MSG_ERRQUEUE)
        return sock_recv_errqueue(iocb, sk, msg, len, flags);

    skb = skb_recv_datagram(sk, flags, noblock, &err);
    if (!skb)
        return err;

    copied = skb->len;
    if (len < copied) {
        if (!(flags & MSG_TRUNC))
            copied = len;
    }

    err = skb_copy_datagram_msg(skb, 0, msg, copied);
    if (err)
        goto out;

    if (addr_len) {
        *addr_len = sizeof(struct sockaddr_in6);
        iph = ipv6_hdr(skb);
        saddr = &iph->saddr;
        daddr = &iph->daddr;

        if (msg->msg_name) {
            struct sockaddr_in6 *addr = (struct sockaddr_in6 *)msg->msg_name;
            memset(addr, 0, sizeof(*addr));
            addr->sin6_family = AF_INET6;
            addr->sin6_port = 0;
            addr->sin6_flowinfo = 0;
            addr->sin6_scope_id = 0;

            if (ipv6_addr_any(&iph->daddr) &&
                tunnel->ip6_session_mapping &&
                tunnel->ip6_session_mapping[skb->skb_iif]) {
                ip6_addr_copy(&addr->sin6_addr, tunnel->ip6_session_mapping[skb->skb_iif]);
            } else {
                ip6_addr_copy(&addr->sin6_addr, daddr);
            }
        }
    }

    if (copied > 0)
        sock_recv_timestamp(msg, sk, skb);

    out:
    kfree_skb(skb);
    return copied ? copied : err;
}

int l2tp_ip6_recvmsg(struct kiocb *iocb, struct sock *sk, struct msghdr *msg,
                     size_t len, int noblock, int flags, int *addr_len)
{
    struct sk_buff *skb;
    int copied = 0, err = 0;
    struct ipv6_pinfo *np = inet6_sk(sk);
    struct in6_addr *saddr, *daddr;

    if (flags & MSG_OOB) {
        return -EINVAL;
    }

    if (flags & MSG_ERRQUEUE) {
        return sock_recv_errqueue(iocb, sk, msg, len, noblock, flags, addr_len);
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        if (flags & MSG_DONTWAIT) {
            return -EAGAIN;
        }

        if (skb) {
            kfree_skb(skb);
        }
        return -EAGAIN;
    }

    copied = skb->len;
    if (len < copied) {
        copied = len;
    }

    err = skb_copy_datagram_to(skb, 0, msg->msg_iobuf, copied, 0);
    if (err) {
        kfree_skb(skb);
        return err;
    }

    if (msg->msg_name) {
        struct sockaddr_in6 *addr = (struct sockaddr_in6 *)msg->msg_name;

        saddr = &skb->pkt_type;
        daddr = &skb->ip6;

        addr->sin6_family = AF_INET6;
        addr->sin6_port = 0;
        addr->sin6_flowinfo = 0;
        addr->sin6_scope_id = 0;
        memcpy(&addr->sin6_addr, daddr, sizeof(struct in6_addr));
        *addr_len = sizeof(struct sockaddr_in6);
    }

    if (flags & MSG_TRUNC) {
        copied = skb->len;
    }

    kfree_skb(skb);

    if (np && (flags & MSG_WAITFORONE))
        np->pending_read = 0;

    return copied;
}

int l2tp_ip6_recvmsg(struct kiocb *iocb, struct sock *sk, struct msghdr *msg,
                     size_t len, int noblock, int flags, int *addr_len)
{
    int cmsg_flag = 0;
    struct sk_buff *skb;
    int copied = 0;
    int ret = 0;
    struct in6_addr *sin6;
    struct sockaddr_in6 *addr;

    if (flags & MSG_OOB) {
        return -EOPNOTSUPP;
    }

    if (flags & MSG_ERRQUEUE) {
        return sock_recv_errqueue(iocb, sk, msg, len, flags, addr_len);
    }

    skb = skb_recv_datagram(sk, flags, noblock, &ret);
    if (!skb) {
        return ret;
    }

    copied = skb->len;
    if (len < copied) {
        copied = len;
        msg->msg_flags |= MSG_TRUNC;
    }

    if (memcpy_to_msg(msg, skb->data, copied)) {
        ret = -EFAULT;
        goto out_free_skb;
    }

    if (addr_len) {
        addr = (struct sockaddr_in6 *)msg->msg_name;
        if (addr) {
            sin6 = (struct in6_addr *)skb->cb;
            addr->sin6_family = AF_INET6;
            addr->sin6_addr = *sin6;
            addr->sin6_port = 0;
            *addr_len = sizeof(*addr);
        }
    }

    if (flags & MSG_CMSG_CLOEXEC)
        cmsg_flag = 1;

    if (cmsg_flag) {
        sock_cmsg_rcv(iocb, sk, msg, skb);
    }

    if (skb->tstamp)
        sock_skb_set_timestamp(msg, skb->tstamp);

out_free_skb:
    kfree_skb(skb);
    return copied ? copied : ret;
}

int l2tp_ip6_recvmsg(struct kiocb *iocb, struct sock *sk, struct msghdr *msg,
                     size_t len, int noblock, int flags, int *addr_len)
{
    int copied = 0;
    struct sk_buff *skb;
    struct in6_addr *saddr, *daddr;

    skb = skb_recv_datagram(sk, flags, noblock, addr_len);
    if (!skb)
        return -EAGAIN;

    copied = skb->len;
    if (len < copied) {
        copied = -EINVAL;
        goto out_free_skb;
    }

    if (memcpy_to_msg(msg, skb->data, skb->len))
        copied = -EFAULT;

    saddr = &ipv6_hdr(skb->data)->saddr;
    daddr = &ipv6_hdr(skb->data)->daddr;

    if (msg->msg_name) {
        struct sockaddr_in6 *addr;
        addr = (struct sockaddr_in6 *)msg->msg_name;
        memset(addr, 0, sizeof(*addr));
        addr->sin6_family = AF_INET6;
        addr->sin6_addr = *daddr;
        addr->sin6_port = 0;
        *addr_len = sizeof(*addr);
    }

    sock->sk_stamp = skb->tstamp;

out_free_skb:
    kfree_skb(skb);
    return copied;
}

ssize_t l2tp_ip6_recvmsg(struct kiocb *iocb, struct sock *sk,
                         struct msghdr *msg, size_t len, int noblock,
                         int flags, int *addr_len)
{
    struct ipv6_pinfo *np = inet6_sk(sk);
    struct in6_addr *sin6;
    struct sockaddr_in6 *addr;
    struct sk_buff *skb;
    ssize_t copied = 0;
    int peeking = flags & MSG_PEEK;
    int has_trunc = 0;
    int has_tx = 0;

    if (flags & (MSG_OOB))
        return -EINVAL;

    skb = skb_recv_datagram(sk, flags, noblock, &has_trunc);
    if (!skb)
        return (flags & MSG_DONTWAIT) ? -EAGAIN : -EWOULDBLOCK;

    len = min_t(size_t, len, skb->len);
    if (peeking)
        skb->len -= len;
    else
        skb_pull(skb, len);

    if (flags & MSG_TRUNC)
        copied = skb->len;
    else
        copied = len;

    if (iov_iter_count(&msg->msg_iter)) {
        int err = skb_copy_datagram_msg(skb, 0, msg, len);
        if (err)
            return err;
    }

    if (addr_len) {
        addr = (struct sockaddr_in6 *)__skb_dst(skb)->addr;

        sin6 = (struct in6_addr *)__skb_dst(skb)->addr;
        sock_update_address(skb, &addr->sin6_addr);

        addr->sin6_family = AF_INET6;
        addr->sin6_port = 0;
        addr->sin6_flowinfo = 0;
        addr->sin6_scope_id = 0;

        *addr_len = sizeof(*addr);
    }

    if (flags & MSG_ERRQUEUE)
        return copied;

    sock_put(skb);
    return copied;
}
